!function(e){function t(t){for(var a,i,p=t[0],o=t[1],m=t[2],f=0,s=[];f<p.length;f++)i=p[f],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&s.push(n[i][0]),n[i]=0;for(a in o)Object.prototype.hasOwnProperty.call(o,a)&&(e[a]=o[a]);for(c&&c(t);s.length;)s.shift()();return d.push.apply(d,m||[]),r()}function r(){for(var e,t=0;t<d.length;t++){for(var r,i=d[t],p=!0,o=1;o<i.length;o++)r=i[o],0!==n[r]&&(p=!1);p&&(d.splice(t--,1),e=a(a.s=i[0]))}return e}function a(t){if(i[t])return i[t].exports;var r=i[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var i={},n={20:0},d=[];a.m=e,a.c=i,a.d=function(e,t,r){a.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,t){if(1&t&&(e=a(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)a.d(r,i,function(t){return e[t]}.bind(null,i));return r},a.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(t,"a",t),t},a.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},a.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=t,p=p.slice();for(var m=0;m<p.length;m++)t(p[m]);var c=o;d.push([100,0]),r()}({100:function(e,t,r){"use strict";r.r(t);var a=r(0);Object(a.a)("de","army",r(101),r(1))},101:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"Sd Kfz 7/1、7/2型半履带防空炮车","description":"<p>德军Sd Kfz 7/1、7/2型半履带防空炮车都是以8吨Sd Kfz 7半履带车为载体，在车体上安装一门防空炮改装成的自行半履带防空炮车。</p><p>1941年，德军就已经将4联装20mm Flak 38型机关炮安装在8吨Sd Kfz 7半履带车上，并投入了战场，但此型炮车直到1944年改进后才命名为Sd Kfz 7/1防空炮车并正式生产，该炮车主要是为德军装甲部队、运输部队和重要目标作防空用，在1944年后一共生产了319辆，其数量在德军的防空炮车系列中也算是较多的了。</p><p>而Sd Kfz 7/2防空炮车是在1942年就开始改装并命名，该炮车安装了一门高平两用的单管37mm Flak 36型机关炮，此炮威力较强，可与苏军坦克对抗，所以该炮车除作防空外，还经常会作为德军战斗的火力支援炮车用；该型炮车生产的数量并不多，一共才生产了123辆。</p><p>德军改装的这两种炮车装甲防护十分薄弱，Sd Kfz 7/1炮车除了火炮防盾外，基本没有装甲防护，而Sd Kfz 7/2炮车后期尽管加装了装甲，但仍显不足，因此它们在战场上的生存率并不高。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_avhtv71&72_11.jpg","description":"<h6>Sd Kfz 7/1型半履带防空炮车</h6><p>Sd Kfz 7/1防空炮车除留下了驾驶员座位外，原Sd Kfz 7装甲车的座位被全部拆除，并在车厢内加装了一块平板，在平板上安装了一门四联装20mm Flak 38型机关炮，车厢四周的网格栏板在战斗时可以放平，以方便防空炮转动射击。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_12.jpg","description":"<h6>Sd Kfz 7/2型半履带防空炮车</h6><p>1942年Sd Kfz 7/2炮车开始改装时，将37mm Flak 36型机关炮直接安装后并末加装甲防护，战斗中很容易就出现车辆受损和车组人员伤亡的情况，1943年后用钢板将驾驶室封闭，车厢前部加装了防盾，使炮车增加了一定的防护能力。该炮车能保持50公里的时速，最大行程可达250米，故能跟上德军装甲部队的前进速度，为其提供防空保护。</p><p>Sd Kfz 7/2型半履带防空炮车后部经常会加挂一辆弹药拖车，以保证战斗时弹药的供应。</p>","caption":""}],"part2title":"战场上的Sd Kfz 7/1、7/2型半履带防空炮车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv71&72_21.jpg","description":"1943年春季，隶属德军第66高射炮营的一辆Sd Kfz 7/1半履带防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_22.jpg","description":"1941年7-8月间，德军第66高射炮营5连的一辆4管20mm Flak 38机关炮Sd Kfz 7/1半履带防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_23.jpg","description":"1941年7月，爱沙尼亚高里地区附近的杜纳堡-列宁格勒路上，3辆负责防空的德军第6装甲师Sd Kfz 7/1半履带防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_24.jpg","description":"1943年五月下旬，特鲁布切夫斯克，德军第290高射炮营的一辆安装4管20mm Flak 38机关炮的Sd Kfz 7/1半履带防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_25.jpg","description":"1943年底生产的Sd Kfz 7/1半履带防空炮车，它的驾驶舱室和车前格栅已经加装了80mm厚的装甲钢板。图中这辆炮车有7名车组成员，炮车正停靠在一树林边空地上，以保证火炮有良好的视野。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_26.jpg","description":"图中这辆由德国博格沃德公司生产的Sd Kfz 7/1率属于德军第22高射炮营（车号WH-670463），注意炮车上的4管机关炮被拆除了上方两根炮管。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_27.jpg","description":"Sd Kfz 7/1炮车上的4管机关炮是一种对付低空目标十分有效和让人恐惧的防空武器，在实战中备受德军部队的高度赞扬，该炮车后部常常会牵挂一辆Sd Ah 56挂车，为炮车装载备用弹药和零部件。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_28.jpg","description":"安装4管20mm Flak 38机关炮的Sd Kfz 7/1半履带防空炮车常负有铁路运输时的防空职责。由于其车体超宽，铁路运输时其围栏不能放倒。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_29.jpg","description":"1945年4月，停靠在树林中的德军一辆Sd Kfz 7/2半履带防空炮车。由于装甲防护薄弱，炮车要依靠树林作掩护，该炮车37炮的炮口正指向高空，估计停靠处是德军的一处防空阵地。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_30.jpg","description":"一辆在德国某重点工厂防空阵地上的Sd Kfz 7/2半履带装甲自行炮车。该炮车已经过改装，在舱室和车前格栅加装了80mm厚的装甲钢板。并拖挂了Sd Ah 57弹药车。炮车上一德军正在37mm Flak 36高射炮炮位上作对空观察。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_31.jpg","description":"一辆德国空军的Sd Kfz 7/2半履带防空炮车正在军官指挥下作战斗准备，该炮车后部挂有用于存放弹药Sd Ah 57弹药车。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_32.jpg","description":"Sd Kfz 7/2半履带自行炮车由于装甲防护薄弱，无法有效应对敌方坦克的攻击，图中就是一辆因此被击毁的Sd Kfz 7/2半履带防空炮车，该炮车隶属于德军“大德意志”师属高射炮1营。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_33.jpg","description":"1944年7月中旬，在维尔纳地区推进的德军“冯·沃森战斗群”，图片中是一辆隶属德国空军的Sd Kfz 7/2半履带防空炮车，行进中的炮车高射炮正指向12点钟方向。","caption":""},{"image":"imgs/de/army/de_army_avhtv71&72_34.jpg","description":"1941年春季，隶属德军第66高射炮营的一辆Sd Kfz 7/1半履带防空炮车。","caption":""}]}')}});